from pathlib import Path
import json,csv,html,shutil
from PIL import Image,ImageOps
ROOT=Path(__file__).parent; D=ROOT/'dist'; A=D/'assets';A.mkdir(parents=True,exist_ok=True)
# Only owner-supplied product photographs are packaged; downloaded press images stay outside the site.
imgs=json.loads((ROOT.parent/'images.json').read_text()) if (ROOT.parent/'images.json').exists() else []
for index,name in [(45,'hero'),(16,'bottle'),(23,'jar'),(40,'barrel'),(19,'gourd')]:
 if imgs:
  im=ImageOps.exif_transpose(Image.open(ROOT.parent/imgs[index])).convert('RGB');im.thumbnail((1400,1600));im.save(A/(name+'.webp'),'WEBP',quality=86)
C=json.loads((ROOT/'content.json').read_text())
def esc(x):return html.escape(str(x),quote=True)
products=C['products'];cats={p['slug']:p for p in products}
logo='<span class="brand-seal" aria-hidden="true">♛</span><span>SÂM NỮ HOÀNG<small>TỪ CỘI NGUỒN · ĐẾN GIÁ TRỊ</small></span>'
def url(slug=''):return base+slug+('/' if slug else '')
def link(slug,label,cl=''):return f'<a class="{cl}" href="{url(slug)}">{label}</a>'
def photo(name,alt,cl='',eager=False):return f'<img class="{cl}" src="{base}assets/{name}.webp" alt="{esc(alt)}" width="1000" height="1300" {"fetchpriority=high" if eager else "loading=lazy"}>'
def breadcrumb(label):return f'<div class="breadcrumb">{link("","Trang chủ")}<span>/</span>{label}</div>'
def intro(kicker,title,text):return f'<section class="page-intro wrap">{breadcrumb(title)}<p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{text}</p></section>'
def card(p):
 visual=photo('bottle',p['name']) if p['slug']=='ruou-sam' else f'<div class="category-art art-{p["slug"]}" aria-hidden="true"><span>{p["number"]}</span><b>{p["short"]}</b><i>SÂM NỮ HOÀNG</i></div>'
 return f'<article class="product-card" data-category="{p["slug"]}"><a class="card-image" href="{url("san-pham/"+p["slug"])}">{visual}<span class="status">{p["tag"]}</span></a><div class="card-copy"><p class="eyebrow">{p["label"]}</p><h3>{link("san-pham/"+p["slug"],p["name"])}</h3><p>{p["desc"]}</p>{link("san-pham/"+p["slug"],"Khám phá danh mục ↗","text-link")}</div></article>'
def source_cards(limit=None):
 arr=C['sources'][:limit] if limit else C['sources']
 return ''.join(f'<article class="source-card"><p class="eyebrow">{esc(s["publisher"])}</p><h3><a href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer">{esc(s["title"])}</a></h3><div class="source-bottom"><span>{esc(s["date"])}</span><a href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer">Đọc tại nguồn ↗</a></div></article>' for s in arr)
def policies(kind):
 data=C['policies'][kind]
 return intro('THÔNG TIN HỖ TRỢ',data['title'],'Thông tin phục vụ việc tìm hiểu và giao dịch với Sâm Nữ Hoàng.')+f'<section class="wrap reading">'+''.join(f'<h2>{esc(x[0])}</h2><p>{esc(x[1])}</p>' for x in data['sections'])+'</section>'
def content(slug):
 if slug=='':
  return f'''<section class="hero"><div class="hero-copy"><p class="eyebrow gold">SÂM NỮ HOÀNG · BỘ SƯU TẬP</p><h1>Tinh túy từ sâm.<br><em>Trân quý từng<br>giá trị.</em></h1><p>Khám phá Sâm Nữ Hoàng qua các dòng sâm tươi, sâm khô, rượu sâm và cao sâm.</p><div class="hero-actions">{link('san-pham','Khám phá sản phẩm <span>↗</span>','btn light')}{link('gioi-thieu','Câu chuyện thương hiệu','quiet')}</div><div class="hero-note"><span>01 — 04</span><span>TỪ NGUYÊN LIỆU ĐẾN THÀNH PHẨM</span></div></div><div class="hero-image">{photo('hero','Bình Ngự Vị Nữ Hoàng Tưu trong ảnh sản phẩm do chủ dự án cung cấp',eager=True)}<div class="image-caption"><span>RƯỢU SÂM</span><strong>Ngự Vị Nữ Hoàng Tưu</strong><a href="{url('san-pham/ruou-sam')}" aria-label="Xem Ngự Vị Nữ Hoàng Tưu">↗</a></div></div></section>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">BỐN DÒNG SẢN PHẨM</p><h2>Mỗi lựa chọn,<br>một cách trân quý.</h2></div><div><p>Từ sâm nguyên liệu đến các dạng chế biến.<br>Tìm hiểu từng danh mục để lựa chọn phù hợp.</p>{link('san-pham','Xem tất cả sản phẩm ↗','text-link')}</div></div><div class="product-grid">{''.join(card(p) for p in products)}</div></section>
<section class="feature wrap"><div class="feature-image">{photo('jar','Bình rượu Ngự Vị Nữ Hoàng Tưu có nhãn đỏ')}</div><div class="feature-copy"><p class="eyebrow">DÒNG RƯỢU SÂM</p><h2>Ngự Vị<br><em>Nữ Hoàng Tưu.</em></h2><p>Một góc nhìn gần hơn về dòng rượu sâm qua những hình ảnh sản phẩm thực tế. Khám phá các kiểu bình và chai trong bộ sưu tập.</p>{link('san-pham/ruou-sam','Xem hình ảnh & chi tiết ↗','btn dark')}<small>Sản phẩm có cồn · Chỉ dành cho người từ 18 tuổi.</small></div></section>
<section class="story-band"><div class="wrap story-inner"><p class="eyebrow gold">SÂM NỮ HOÀNG</p><h2>Hiểu nguồn gốc.<br><em>Chọn giá trị.</em></h2><div><p>Chúng tôi đang xây dựng không gian giới thiệu doanh nghiệp, sản phẩm và nguồn thông tin tham khảo về Sâm Nữ Hoàng.</p><p>Hồ sơ doanh nghiệp, nguồn nguyên liệu và thông tin sản phẩm sẽ được cập nhật theo tài liệu chính thức.</p>{link('gioi-thieu','Tìm hiểu về chúng tôi ↗','text-link')}</div></div></section>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">GÓC THÔNG TIN</p><h2>Đọc thêm về Sâm Nữ Hoàng.</h2></div>{link('kien-thuc','Thư viện nguồn tham khảo ↗','text-link')}</div><div class="sources-grid">{source_cards(3)}</div></section>
<section class="wrap contact-strip"><div><p class="eyebrow">KẾT NỐI CÙNG SÂM NỮ HOÀNG</p><h2>Bắt đầu từ điều bạn quan tâm.</h2></div>{link('lien-he','Thông tin liên hệ ↗','btn dark')}</section>'''
 if slug=='san-pham':return intro('DANH MỤC SẢN PHẨM','Từ sâm, mở ra nhiều lựa chọn.','Khám phá bốn dòng sản phẩm. Giá bán và quy cách sẽ được bổ sung theo hồ sơ chính thức.')+f'<section class="wrap"><div class="filters" aria-label="Lọc sản phẩm"><button class="active" data-filter="all" aria-pressed="true">Tất cả</button>'+''.join(f'<button data-filter="{p["slug"]}" aria-pressed="false">{p["short"]}</button>' for p in products)+f'</div><div class="product-grid">'+''.join(card(p) for p in products)+'</div></section>'
 if slug.startswith('san-pham/'):
  p=cats[slug.split('/')[-1]];wine=p['slug']=='ruou-sam'
  visual=photo('hero',p['name'],eager=True) if wine else f'<div class="category-art detail-art art-{p["slug"]}"><span>{p["number"]}</span><b>{p["short"]}</b><i>HÌNH ẢNH SẢN PHẨM ĐANG CẬP NHẬT</i></div>'
  return f'<div class="wrap">{breadcrumb(link("san-pham","Sản phẩm")+" / "+p["short"])}</div><section class="wrap detail"><div class="detail-visual">{visual}</div><div><p class="eyebrow">{p["label"]}</p><h1>{p["name"]}</h1><p class="lead">{p["desc"]}</p><p class="availability">Thông tin sản phẩm đang được hoàn thiện</p><dl>'+''.join(f'<div><dt>{label}</dt><dd>Đang cập nhật</dd></div>' for label in (['Dung tích','Nồng độ cồn','Thành phần','Giá bán'] if wine else ['Quy cách','Nguồn nguyên liệu','Bảo quản','Giá bán']))+f'</dl><button class="btn dark" data-add="{p["slug"]}">Lưu vào danh sách quan tâm <span>＋</span></button><p class="fine">Danh sách được lưu trên thiết bị của bạn. Chưa phát sinh đơn hàng hoặc thanh toán.</p>'+('<p class="alcohol">Dành cho người từ 18 tuổi. Không sử dụng rượu bia khi lái xe.</p>' if wine else '')+'</div></section>'+ (f'<section class="wrap section"><p class="eyebrow">HÌNH ẢNH THỰC TẾ</p><h2>Một bộ sưu tập, nhiều góc nhìn.</h2><div class="gallery">'+''.join(f'<button class="gallery-item" data-image="{base}assets/{n}.webp" aria-label="Phóng to hình {i+1}">{photo(n,"Ảnh sản phẩm Ngự Vị Nữ Hoàng Tưu — góc nhìn "+str(i+1))}<span>Xem ảnh ＋</span></button>' for i,n in enumerate(['bottle','jar','barrel','gourd']))+'</div></section>' if wine else '')+f'<section class="wrap reading"><h2>Thông tin cần biết</h2><p>{p["note"]}</p><p>Thành phần, hướng dẫn sử dụng, xuất xứ và các thông tin liên quan sẽ được công bố sau khi có tài liệu xác nhận từ doanh nghiệp.</p></section>'
 if slug=='gioi-thieu':return intro('VỀ CHÚNG TÔI','Sâm Nữ Hoàng.<br>Không gian kết nối những giá trị.','Website giới thiệu doanh nghiệp và các dòng sản phẩm từ sâm, được xây dựng để bạn tìm hiểu thông tin một cách rõ ràng.')+f'<section class="wrap about-layout"><div class="about-number">SÂM<br><em>NỮ HOÀNG</em><span>TỪ CỘI NGUỒN · ĐẾN GIÁ TRỊ</span></div><div><h2>Từ nguồn thông tin<br>đến lựa chọn sản phẩm.</h2><p>Chúng tôi tập trung giới thiệu bốn nhóm sản phẩm: sâm tươi, sâm khô, rượu sâm và cao sâm. Dòng rượu Ngự Vị Nữ Hoàng Tưu hiện có hình ảnh thực tế để tham khảo.</p><p>Thông tin pháp nhân, lịch sử doanh nghiệp, vùng nguyên liệu và hồ sơ chất lượng đang được chuẩn bị để bổ sung vào website.</p>{link("san-pham","Khám phá danh mục ↗","text-link")}</div></section><section class="wrap section"><p class="eyebrow">HỒ SƠ DOANH NGHIỆP</p><h2>Thông tin đang hoàn thiện.</h2><div class="info-grid">'+''.join(f'<div><span>{n}</span><h3>{t}</h3><p>Đang cập nhật theo hồ sơ chính thức.</p></div>' for n,t in [('01','Pháp nhân & địa chỉ'),('02','Vùng nguyên liệu'),('03','Hồ sơ chất lượng')])+'</div></section>'
 if slug=='kien-thuc':return intro('KIẾN THỨC & NGUỒN THAM KHẢO','Hiểu thêm về Sâm Nữ Hoàng.','Các nguồn đọc thêm được chọn từ bộ tài liệu đã thu thập. Mỗi liên kết dẫn trực tiếp đến đơn vị xuất bản.')+f'<section class="wrap"><div class="editor-note">Nội dung tại nguồn là thông tin tham khảo; không thay thế hồ sơ chất lượng hoặc thông tin của sản phẩm được giới thiệu trên website.</div><div class="sources-grid">{source_cards()}</div></section>'
 if slug=='lien-he':return intro('LIÊN HỆ','Kết nối cùng Sâm Nữ Hoàng.','Chọn sản phẩm bạn quan tâm và chuẩn bị nội dung cần trao đổi.')+f'<section class="wrap contact-layout"><div><p class="eyebrow">THÔNG TIN DOANH NGHIỆP</p><h2>Chúng tôi đang hoàn thiện<br>các kênh liên hệ.</h2><dl><div><dt>Điện thoại / Zalo</dt><dd>Đang cập nhật</dd></div><div><dt>Email</dt><dd>Đang cập nhật</dd></div><div><dt>Địa chỉ</dt><dd>Đang cập nhật</dd></div><div><dt>Thời gian hỗ trợ</dt><dd>Đang cập nhật</dd></div></dl><p>Thông tin chính thức sẽ được công bố tại đây khi có xác nhận từ doanh nghiệp.</p></div><div class="inquiry-panel"><p class="eyebrow">DANH SÁCH CỦA BẠN</p><h2>Sản phẩm quan tâm <span id="list-count">0</span></h2><div id="inquiry-list"></div><label for="inquiry-note">Nội dung muốn tìm hiểu thêm</label><textarea id="inquiry-note" rows="4" placeholder="Ví dụ: quy cách, giá bán, nguồn nguyên liệu…"></textarea><button id="download-inquiry" class="btn dark">Tải danh sách quan tâm ↓</button><p class="fine">Tệp được tạo trên thiết bị của bạn. Nội dung chưa được gửi tới doanh nghiệp.</p></div></section>'
 if slug in C['policies']:return policies(slug)
 if slug=='404':return intro('KHÔNG TÌM THẤY TRANG','Đường dẫn chưa có nội dung.','Bạn có thể trở lại trang chủ hoặc khám phá danh mục sản phẩm.')+f'<div class="wrap">{link("","Về trang chủ ↗","btn dark")}</div>'
pages={'':('Sâm Nữ Hoàng | Sâm tươi, sâm khô, rượu sâm, cao sâm','Khám phá các dòng sản phẩm Sâm Nữ Hoàng và hình ảnh Ngự Vị Nữ Hoàng Tưu.'),'gioi-thieu':('Giới thiệu | Sâm Nữ Hoàng','Giới thiệu website và hồ sơ doanh nghiệp Sâm Nữ Hoàng.'),'san-pham':('Sản phẩm | Sâm Nữ Hoàng','Danh mục sâm tươi, sâm khô, rượu sâm và cao sâm.'),'kien-thuc':('Kiến thức | Sâm Nữ Hoàng','Nguồn tham khảo về Sâm Nữ Hoàng.'),'lien-he':('Liên hệ | Sâm Nữ Hoàng','Thông tin liên hệ và danh sách sản phẩm quan tâm.'),'404':('Không tìm thấy trang | Sâm Nữ Hoàng','Đường dẫn chưa có nội dung.')}
for p in products:pages['san-pham/'+p['slug']]=(p['name']+' | Sâm Nữ Hoàng',p['desc'])
for k,p in C['policies'].items():pages[k]=(p['title']+' | Sâm Nữ Hoàng',p['title'])
for slug,(title,desc) in pages.items():
 base='../'*len(slug.split('/')) if slug and slug!='404' else './'
 nav=''.join(link(s,t,'nav-link '+('current' if s and (slug==s or slug.startswith(s+'/')) else '')) for s,t in [('','Trang chủ'),('gioi-thieu','Giới thiệu'),('san-pham','Sản phẩm'),('kien-thuc','Kiến thức'),('lien-he','Liên hệ')])
 body=content(slug)
 page=f'''<!DOCTYPE html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#163f35"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{base}assets/style.css"><script defer src="{base}assets/app.js"></script></head><body data-base="{base}"><a class="skip" href="#main">Đến nội dung chính</a><div class="topline">SÂM NỮ HOÀNG <span>·</span> TỪ CỘI NGUỒN ĐẾN GIÁ TRỊ</div><header><div class="header-inner"><a class="brand" href="{url()}">{logo}</a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav" aria-label="Mở trình đơn">☰</button><nav id="main-nav" aria-label="Điều hướng chính">{nav}</nav><a class="saved-link" href="{url('lien-he')}" aria-label="Danh sách quan tâm">Quan tâm <span class="saved-count">0</span></a></div></header><main id="main">{body}</main><footer><div class="wrap footer-grid"><div><a class="brand" href="{url()}">{logo}</a><p>Sâm tươi · Sâm khô<br>Rượu sâm · Cao sâm</p></div><div><h3>Khám phá</h3>{link('gioi-thieu','Giới thiệu')}{link('san-pham','Sản phẩm')}{link('kien-thuc','Kiến thức')}{link('lien-he','Liên hệ')}</div><div><h3>Hỗ trợ khách hàng</h3>{''.join(link(k,v['title']) for k,v in C['policies'].items())}</div><div><h3>Thông tin liên hệ</h3><p>Điện thoại, email và địa chỉ<br>đang được cập nhật.</p>{link('lien-he','Xem thông tin ↗')}</div></div><div class="wrap footer-bottom"><span>© 2026 Sâm Nữ Hoàng</span><span>Thông tin sản phẩm đang được hoàn thiện.</span></div></footer><div class="toast" role="status" aria-live="polite"></div><dialog id="lightbox"><button class="close-dialog" aria-label="Đóng ảnh">×</button><img alt="Ảnh sản phẩm phóng to"></dialog></body></html>'''
 target=D/'404.html' if slug=='404' else D/slug/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(page)
(D/'.nojekyll').touch();(D/'robots.txt').write_text('User-agent: *\nAllow: /\n')
print('Generated',len(pages),'pages')
